import { Modal } from '@kampus-gratis/components/molecules';
import Image from 'next/image';
import { useProfile, useUpdateAvatar } from '../../../../hooks/profile/hook';
import { toast } from 'react-toastify';

export const Dialog = ({
  ...props
}: {
  open: boolean;
  setOpen: (open: boolean) => void;
  sourceImg: any;
  avatar: any;
}) => {
  const { mutate } = useUpdateAvatar();
  const { refetch } = useProfile();
  const handleUpload = () => {
    mutate(
      { avatar: props.avatar },
      {
        onSuccess: () => {
          props.setOpen(false);
          toast.success('Berhasil Mengubah Avatar', {
            position: 'top-right',
            autoClose: 5000,
            hideProgressBar: false,
            closeOnClick: true,
            pauseOnHover: true,
            draggable: true,
            progress: undefined,
            theme: 'light',
          });
          refetch();
        },
      }
    );
  };

  return (
    <Modal
      lookup={props.open}
      onClose={() => props.setOpen(false)}
      hasButton={true}
      // hasImage={true}
      withClose={true}
      widthModal={'max-w-2xl'}
    >
      <div className="flex flex-col">
        <div className="p-8">
          <Image
            src={props.sourceImg}
            width={200}
            height={200}
            alt="image upload"
            className="w-[200px] h-[200px] rounded-full object-cover bg-center"
          />
        </div>
        <button type="button" onClick={handleUpload}>
          Upload avatar
        </button>
      </div>
    </Modal>
  );
};

apps/backend/src/models/Otps.ts.content:
import * as Sequelize from 'sequelize';
import { DataTypes, Model, Optional } from 'sequelize';

export interface OtpsAttributes {
  id: string;
  email: string;
  otp: string;
  otpType: string;
  expirationTime?: Date;
  createdAt: Date;
  updatedAt: Date;
  deletedAt?: Date;
  token?: string;
}

export type OtpsPk = "id";
export type OtpsId = Otps[OtpsPk];
export type OtpsOptionalAttributes = "expirationTime" | "deletedAt" | "token";
export type OtpsCreationAttributes = Optional<OtpsAttributes, OtpsOptionalAttributes>;

export class Otps extends Model<OtpsAttributes, OtpsCreationAttributes> implements OtpsAttributes {
  id!: string;
  email!: string;
  otp!: string;
  otpType!: string;
  expirationTime?: Date;
  createdAt!: Date;
  updatedAt!: Date;
  deletedAt?: Date;
  token?: string;


  static initModel(sequelize: Sequelize.Sequelize): typeof Otps {
    return Otps.init({
    id: {
      type: DataTypes.UUID,
      allowNull: false,
      primaryKey: true
    },
    email: {
      type: DataTypes.STRING(255),
      allowNull: false
    },
    otp: {
      type: DataTypes.STRING(255),
      allowNull: false
    },
    otpType: {
      type: DataTypes.STRING(255),
      allowNull: false,
      field: 'otp_type'
    },
    expirationTime: {
      type: DataTypes.DATE,
      allowNull: true,
      field: 'expiration_time'
    },
    createdAt: {
      type: DataTypes.DATE,
      allowNull: false,
      field: 'created_at'
    },
    updatedAt: {
      type: DataTypes.DATE,
      allowNull: false,
      field: 'updated_at'
    },
    deletedAt: {
      type: DataTypes.DATE,
      allowNull: true,
      field: 'deleted_at'
    },
    token: {
      type: DataTypes.STRING(255),
      allowNull: true
    }
  }, {
    sequelize,
    tableName: 'otps',
    schema: 'public',
    timestamps: false
  });
  }
}

