                  </button>
                  <button
                    className="flex justify-start h-[38px] relative hover:bg-neutral-100 w-full bg-white "
                    onClick={() => {
                      setFilter('ACCEPTED');
                      refetchPengajuan();
                      router.push(`/pengajuan/administrasi?page=1`);
                    }}
                  >
                    <div
                      className={`h-full w-[5px] ${
                        filter == 'ACCEPTED' ? 'bg-blue-base' : 'bg-white'
