    id: {
      type: DataTypes.UUID,
      allowNull: false,
      primaryKey: true
    },
    consultationTypeId: {
      type: DataTypes.UUID,
      allowNull: false,
      field: 'consultation_type_id'
    },
    consultantId: {
      type: DataTypes.UUID,
      allowNull: false,
      field: 'consultant_id'
    },
    clientId: {
      type: DataTypes.UUID,
      allowNull: false,
      field: 'client_id'
    },
    createdAt: {
      type: DataTypes.DATE,
      allowNull: false,
      field: 'created_at'
    },
    updatedAt: {
      type: DataTypes.DATE,
      allowNull: false,
      field: 'updated_at'
    },
    deletedAt: {
      type: DataTypes.DATE,
      allowNull: true,
      field: 'deleted_at'
    }
  }, {
    sequelize,
