import Image from 'next/image';
import Link from 'next/link';
import { useRouter } from 'next/navigation';

export default function FeatureCard({
  src,
  alt,
  text,
  buttonText,
  href,
  textColor = '',
  title,
}: {
  src: string;
  alt: string;
  text: string;
  buttonText?: string;
  href: string;
  textColor?: string;
  title?: string;
}) {
  const router = useRouter();

  const handleClick = () => {
    !buttonText && router.push(href);
  };

  return (
    <div
      className={`
      w-full rounded-lg shadow-md flex items-center flex-col py-6 text-center ${
        !buttonText &&
        'cursor-pointer hover:shadow-md hover:bg-gray-100/50 transition'
      }`}
      onClick={handleClick}
