} from '../../../types/pengajuan/krs/types';
import {
  AcceptKrsRequest,
  GetStudyPlanRequest,
  RejectKrsRequest,
} from './request';

export const useGetStudyPlanRequest = (
  page: number,
  search: string,
  limit: number,
  sort_by: string
): UseQueryResult<TAllStudyplanRequestResponse> =>
