                <h1 className="font-[600] sm: font-bold lg:text-[18px] text-[12px]">
                  {matchingRank.autor?.npm}
                </h1>
              </div>
            </div>
            <div className="flex items-center">
              <h1 className="font-[600] font-bold lg:text-[16px] text-[12px] text-primary-600">
