            columns={columns}
            className=""
          >
            {data?.data &&
              data?.data?.map((data: TKRSRequest, index: number) => {
                return (
                  <tr key={index} className="border-b">
                    <td className="text-center">
                      <div className="flex justify-center items-center py-2">
