                      </div>
                    </td>
                    <td>
                      {data.status === 'PENDING' ? (
                        <div className="flex justify-around items-center w-full py-2 ">
                          <div
                            className="relative group"
                            onClick={() =>
                              handleAccept(data.student_id, data.subject_id)
