                  </tr>
                );
              })}
          </ReusableTable>
        )}

        <Pagination
          onPageChange={handlePageChange}
          totalPages={data?.meta?.max_page || 1}
          currentPage={data?.meta?.current_page || 1}
        />
      </div>
      {isAccept ? (
        <ModalAcc
          isOpen={isModalOpen}
          closeModal={handleClosePopUpSubmit}
          student_id={selectedStudentId}
