      // Ambil sisa percobaan
      const storedAttempts = localStorage.getItem('remainingAttempt');
      setRemainingAttempt(storedAttempts ? parseInt(storedAttempts) : 3);

      setIsLoading(false);
    }, 500); // Simulasi delay 500ms
