import { ContentLayoutTypes } from "../../../../../types/score-sertificate";
import { FC, ReactElement } from "react";

export const ContentLayouts: FC<ContentLayoutTypes> = ({
  children,
  className = "",
  withFlex = true,
  withGrid = false,
  withGap = true,
}): ReactElement => {
  const flexContent = `${withFlex ? `flex flex-col ${withGap ? "gap-y-[50px]" : ""}` : ""}`;

