  //       const idQuestion = data.data.questions_answers[index].id;
  //       const idAnswer = selected.answer;

  //       questionAnswerPairs.push({ question: idQuestion, answer: idAnswer });
  //     }
  //   });

  //   // Construct the result object
  //   const result = {
  //     id: id,
  //     req: {
  //       questions_answers:
  //         questionAnswerPairs.length > 0
  //           ? questionAnswerPairs
  //           : [
  //               {
