                setPopUpSend(false);
              }}
              type={'button'}
            >
              Kembali
            </Button>
            <Button
              className="w-[230px] h-[56px] bg-[#106FA4] rounded-[8px] text-white"
              type={'button'}
              onClick={() => {
                // setPopUpSend(false);
                sendDraft('', {
                  onSuccess: () => {
                    refetch();
                    setPopUpSend(false);
                    setPopupSuccess(true);
                  },
                  onError: (error) => {
                    toast.error(error?.response?.data?.message as string, {
                      position: 'top-right',
                      autoClose: 5000,
                      hideProgressBar: false,
                      closeOnClick: true,
                      pauseOnHover: true,
                      draggable: true,
                      progress: undefined,
                      theme: 'light',
                    });
                  },
                });
              }}
            >
              Lanjut
            </Button>
          </div>
        </PopupModal>
        <PopupModal
          onClose={() => setPopupSuccess(false)}
          icon={'/icons/rencana-studi/Success.svg'}
          popupTitle="Berhasil"
          lookup={getPopupSuccess}
