          <div className="flex gap-3 my-2 py-4 justify-center">
            <Button
              className="w-[230px] h-[56px] border-[#106FA4] border-2 rounded-[8px] text-[#106FA4] "
              onClick={(e) => {
                setPopupAdd(false);
                setPopupSuccess(false);
                onMove(e);
              }}
