              className="w-[230px] h-[56px] bg-[#106FA4] rounded-[8px] text-white"
              type={'button'}
              onClick={() => setPopupAdd(false)}
            >
              Kembali
            </Button>
          </div>
        </PopupModal>
      </div>
    </>
  );
};

