export const PalingSeringSection: FC = (): ReactElement => {
  const { data, isLoading } = useGetFaq();

  const faqData = data?.data;

  if (isLoading) {
    return <LoadingSpinner />;
  }

  return (
    <section className="flex flex-col items-center bg-white w-full pb-8">
