  TQuizTakeResponse,
} from '../../../types/quiz';

export const quizListRequest = async (
  subject_id: string,
  session_id: string
): Promise<TQuizResponse> => {
  const { data } = await api.get(`v2/my-study/subjects/${subject_id}/sessions/${session_id}/quizzes`);
  return data;
}

export const quizDescGetRequest = async (
  subject_id: string,
  session_id: string,
