        <div className="max-w-[1440px] mx-auto flex justify-between  transition-all ease-in-out duration-300 flex-col">
          <TopNav {...props} />
        </div>
      </header>
      {session && includesPath && <BottomNav {...props} />}
    </Fragment>
  );
};

