import { FC, Fragment, useState } from 'react';
import { TDiscussinCardProps } from './types';
import Image from 'next/image';
import { AiOutlineLike, AiFillLike } from 'react-icons/ai';
import { GoCommentDiscussion } from 'react-icons/go';
import Avatar from 'react-avatar';
import { useQueryClient } from '@tanstack/react-query';
import {
  useLikeComment,
  useLikeDiscussion,
  useLikeReply,
} from '../../../hooks/ruang-diskusi/hooks';
import { CommentInput } from '../commentInput';
import { ImagePreview } from '../../../components/ruang-diskusi/imagePreview';
import { toast } from 'react-toastify';

export const DiscussionCard: FC<TDiscussinCardProps> = ({
  avatar,
  hasImage,
  text,
  imgSource,
  userName,
  title,
  time,
  type,
  countLikes,
  children,
  option,
  id,
  isLiked,
  commentId,
  discussionId,
}) => {
  const queryClient = useQueryClient();
  const { mutate, isSuccess } = useLikeDiscussion(id as string);
  const { mutate: mutateLikeComment, isSuccess: isSuccessLikeComment } =
    useLikeComment(id as string);
  const {
    mutate: mutateLikeReply,
    isLoading: isLoadingLikeReply,
    isSuccess: isSuccessLikeReply,
  } = useLikeReply(id as string);

  const handleSubmit = async () => {
    type === 'post'
      ? mutate({
          onSuccess: () => {
            queryClient.invalidateQueries(['get-all-discussion']);
          },
        })
      : type === 'comment'
      ? mutateLikeComment({
          onSuccess: () => {
            queryClient.invalidateQueries(['get-all-comment', discussionId]);
          },
        })
      : mutateLikeReply({
          onSuccess: () => {
            queryClient.invalidateQueries([
              'get-all-replies',
              discussionId,
              id,
            ]);
          },
        });
  };

  if (isSuccess) {
    queryClient.invalidateQueries(['get-all-discussion']);
  }

  if (isSuccessLikeComment) {
    queryClient.invalidateQueries(['get-all-comment', discussionId]);
  }

  if (isSuccessLikeReply) {
    queryClient.invalidateQueries(['get-all-replies', discussionId, commentId]);
    // console.log(discussionId, id);
  }

  const [isCommentOpen, setCommentOpen] = useState(false);
  return (
    <Fragment>
      <div
        className={`${
          type === 'post' ? 'bg-neutral-50' : 'bg-neutral-100'
        } px-5 md:px-8 lg:px-10 py-5 mb-1  border-neutral-100 border-2 rounded-md shadow-sm`}
      >
        <div className="relative flex justify-between">
          <section className="flex items-center gap-4 mb-6 border-neutral-100/60">
            {avatar ? (
              <Image
                src={avatar}
                alt={'user avatar'}
                width={36}
                height={36}
                className="bg-white h-9 w-9  flex text-neutral-600 items-center justify-center font-[700] object-cover bg-center rounded-full"
              />
            ) : (
              <Avatar
                name={userName}
                color="#F26800"
                className=" w-[36px] rounded-full h-9"
                size="36"
              />
            )}
            <div className="flex flex-col">
              <h1 className="text-xs font-bold text-neutral-800 md:text-sm">
                {userName}
              </h1>
              <p className="text-xs text-neutral-400">{time}</p>
            </div>
          </section>
          {option}
        </div>
        <section className="text-sm text-neutral-900 z-20">
          {hasImage && Array.isArray(imgSource) && (
            <ImagePreview
              imgSource={imgSource.map((image) => image.url)}
              alt={`imageby ${userName}`}
              type={type}
            />
          )}
          {(type === 'comment' || type === 'reply') && hasImage && (
            <ImagePreview
              imgSource={imgSource.url}
              alt={`imageby${userName}`}
              type={type}
            />
          )}
          {title && (
            <h1 className="mb-3 text-sm font-bold md:text-base">{title}</h1>
          )}

          <p className="pr-0 mb-6 text-xs text-neutral-700 md:text-sm md:pr-4 lg:pr-20 md:mb-8 lg:mb-10">
            {text}
          </p>
          <div className="flex items-center gap-6">
            <div
              // className="flex items-center gap-2 text-[#106FA4] cursor-pointer z-40"
              className="flex items-center gap-2 text-sky-base cursor-pointer z-40"
              onClick={handleSubmit}
            >
              {isLiked ? <AiFillLike /> : <AiOutlineLike />}
              <h1 className="text-xs md:text-sm ">{countLikes} Disukai</h1>
            </div>
            {type !== 'reply' && (
              <div
                // className="flex items-center gap-2 text-[#106FA4] cursor-pointer z-40"
                className="flex items-center gap-2 text-sky-base cursor-pointer z-40"
                onClick={() => {
                  setCommentOpen(!isCommentOpen);
                }}
              >
                <GoCommentDiscussion />
                <h1 className="text-xs md:text-sm">Balas</h1>
              </div>
            )}
          </div>
        </section>
      </div>
      <section
        className={`w-full mb-1 border-2 rounded-md shadow-sm border-neutral-10 ${
          isCommentOpen
            ? 'block max-h-[1000px] transition-all duration-500 opacity-100 ease-in-out translate-y-0'
            : 'none  max-h-0 transition-all duration-300 opacity-0 ease-out -translate-y-12 '
        }`}
      >
        <CommentInput
          id={id}
          type={type === 'post' ? 'comment' : 'reply'}
          discussion_id={discussionId}
        />
      </section>
      {children}
    </Fragment>
  );
};

apps/backend/src/models/Faculties.ts.content:
import * as Sequelize from 'sequelize';
import { DataTypes, Model, Optional } from 'sequelize';

export interface FacultiesAttributes {
  id: string;
  name: string;
  thumbnail: string;
  slug: string;
  createdAt: Date;
  updatedAt: Date;
  deletedAt?: Date;
  thumbnailId?: number;
  code?: string;
}

export type FacultiesPk = "id";
export type FacultiesId = Faculties[FacultiesPk];
export type FacultiesOptionalAttributes = "deletedAt" | "thumbnailId" | "code";
export type FacultiesCreationAttributes = Optional<FacultiesAttributes, FacultiesOptionalAttributes>;

export class Faculties extends Model<FacultiesAttributes, FacultiesCreationAttributes> implements FacultiesAttributes {
  id!: string;
  name!: string;
  thumbnail!: string;
  slug!: string;
  createdAt!: Date;
  updatedAt!: Date;
  deletedAt?: Date;
  thumbnailId?: number;
  code?: string;


  static initModel(sequelize: Sequelize.Sequelize): typeof Faculties {
    return Faculties.init({
    id: {
      type: DataTypes.UUID,
      allowNull: false,
      primaryKey: true
    },
    name: {
      type: DataTypes.STRING(255),
      allowNull: false
    },
    thumbnail: {
      type: DataTypes.STRING(255),
      allowNull: false
    },
    slug: {
      type: DataTypes.STRING(255),
      allowNull: false
    },
    createdAt: {
      type: DataTypes.DATE,
      allowNull: false,
      field: 'created_at'
    },
    updatedAt: {
      type: DataTypes.DATE,
      allowNull: false,
      field: 'updated_at'
    },
    deletedAt: {
      type: DataTypes.DATE,
      allowNull: true,
      field: 'deleted_at'
    },
    thumbnailId: {
      type: DataTypes.INTEGER,
      allowNull: true,
      field: 'thumbnail_id'
    },
    code: {
      type: DataTypes.STRING(255),
      allowNull: true
    }
  }, {
    sequelize,
    tableName: 'faculties',
    schema: 'public',
    timestamps: false
  });
  }
}

apps/kg/modules/mystudy/quiz/score/index.content:
'use client';

import { ArcElement, Chart as ChartJS, Legend, Tooltip } from 'chart.js';
import Link from 'next/link';
import {
  useParams,
  usePathname,
  useRouter,
  useSearchParams,
} from 'next/navigation';
import { FC, ReactElement } from 'react';
import { Doughnut } from 'react-chartjs-2';
import {
  useGetQuizDescById,
  useGetQuizScoreById,
} from '../../../../hooks/mystudy/quiz/hook';
import { TQuizScoreItem } from '../../../../types/quiz';
import { DetailCard } from './DetailCard';
import { StudiKuBreadCumbs } from 'apps/kg/utils/constantStudiKu';
import { BreadCrumb, LoadingSpinner } from '@kampus-gratis/components/atoms';
ChartJS.register(ArcElement, Tooltip, Legend);

export const QuizScoreModule = (): ReactElement => {
  const { subjectId, sessionId, quizId } = useParams();
  const { data: quizScoreData, isLoading } = useGetQuizScoreById(
    quizId as string
  );

  const { data: quizDetail } = useGetQuizDescById(
    subjectId as string,
    sessionId as string,
    quizId as string
  );

  const dataQuizScores: TQuizScoreItem = quizScoreData?.data as TQuizScoreItem;
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const totalQuestion = searchParams.get('total_question');
  const riwayatPath = pathname.replace('mulai/nilai-quiz', 'riwayat-quiz');
  function convertNumberToTens(num: number): number {
    const tens = (num / dataQuizScores?.total_question) * 100;
    return Math.round(tens);
  }
  function changeFormatByMinutes(second: number): string {
    const minutes: number = Math.floor(second / 60);
    const remainingSeconds: number = second % 60;

    return `${minutes} Menit ${remainingSeconds} Detik`;
  }

  const rightAnswer = convertNumberToTens(dataQuizScores?.right || 0);
  const wrongAnswer = convertNumberToTens(dataQuizScores?.wrong || 0);
  const timeElapsed = changeFormatByMinutes(dataQuizScores?.time_elapsed || 0);

  const data = {
    labels: ['Your Score'],
    datasets: [
      {
        data: [rightAnswer, wrongAnswer],
        backgroundColor: ['#43A7FF', '#E5E5E5'],
        borderWidth: 0,
      },
    ],
  };
  const options = {
    plugins: {
      legend: {
        display: false,
      },
      tooltip: {
        enabled: false,
      },
    },
    elements: {
      arc: {
        borderRadius: 10,
      },
    },
    cutout: 150,
  };

  const scoreQuizBreadCrumb = [
    ...StudiKuBreadCumbs,
    {
      name: quizDetail?.data.subject.name,
      link: `/studi-ku/${subjectId}`,
    },
    {
      name: quizDetail?.data.quiz.title,
      link: `/studi-ku/${subjectId}/session/${sessionId}/kuis/${quizId}`,
    },
    {
      name: 'Hasil Quiz',
      link: `/studi-ku/${subjectId}/session/${sessionId}/kuis/${quizId}/mulai/nilai-quiz`,
    },
  ];

  if (isLoading) return <LoadingSpinner />;

  return (
    <>
      <BreadCrumb items={scoreQuizBreadCrumb} />
      <div className="pb-16 px-8 md:px-14 lg:px-16">
        <div className="max-w-[1440px] mx-auto h-[calc(100vh-190px)]">
          <div className="px-6 md:px-8 lg:px-16 xl:px-40 py-14 w-full flex flex-col">
            {quizScoreData && (
              <>
                <section className="w-full py-14 grid grid-cols-1 md:grid-cols-2 gap-x-10 gap-y-20 items-center justify-center">
                  <div className="w-full h-64 relative flex items-center justify-center">
                    <div className="absolute rounded-full border-8 border-neutral-200/70">
                      <Doughnut data={data} options={options} className="p-4" />
                    </div>
                    <div className="flex flex-col items-center">
                      <h1 className="text-4xl text-neutral-900 font-black">
                        {rightAnswer}
                      </h1>
                      <p className="text-xl text-neutral-800">Point</p>
                    </div>
                  </div>
                  <div className="flex justify-between flex-col">
                    <div className="grid grid-cols-1 md:grid-cols-2 w-full gap-4 ">
                      <DetailCard
                        type="trueAnswer"
                        value={dataQuizScores?.right || 0}
                      />
                      <DetailCard
                        type="falseAnswer"
                        value={dataQuizScores?.wrong || 0}
                      />
                      <DetailCard
                        type="timeFinished"
                        value={timeElapsed || 0}
                      />
                      <DetailCard
                        type="totalQuestions"
                        value={dataQuizScores?.total_question || 0}
                      />
                    </div>
                    <div className=" w-full flex justify-center gap-y-3 lg:justify-end mt-10 flex-wrap gap-x-2">
                      <div className="w-full">
                        <Link
                          href={`${riwayatPath}?total_question=${totalQuestion}`}
                        >
                          <button
                            type="button"
                            className="text-sky-base border-2 border-sky-base bg-white hover:opacity-80 w-full h-12 rounded-md shadow-sm font-bold transition-colors ease-out duration-300"
                          >
                            Riwayat Pengerjaan Kuis
                          </button>
                        </Link>
                      </div>
                      {dataQuizScores?.remaining_attempt > 0 && (
                        <div className="w-full ">
                          <Link
                            href={`/studi-ku/${subjectId}/session/${sessionId}/kuis/${quizId}`}
                          >
                            <button
                              type="button"
                              className="bg-sky-base border-2 border-sky-base text-white hover:opacity-80  w-full h-12 rounded-md shadow-sm font-bold  transition-colors ease-out duration-300"
                            >
                              Coba Kembali (Sisa{' '}
                              {dataQuizScores?.remaining_attempt})
                            </button>
                          </Link>
                        </div>
                      )}
                    </div>
                  </div>
                </section>
              </>
            )}
          </div>
        </div>
      </div>
    </>
  );
};

