apps/kg/modules/inbox/hooks/useInfinityS.content:
import { useEffect, useCallback, RefObject } from 'react';

export const useInfiniteScroll = (
  ref: RefObject<HTMLElement>,
  loadMore: () => void,
  hasMore: boolean
) => {
  const handleScroll = useCallback(() => {
    if (ref.current) {
      const { scrollTop, scrollHeight, clientHeight } = ref.current;
      if (scrollTop + clientHeight >= scrollHeight - 20 && hasMore) {
        loadMore();
      }
    }
  }, [ref, loadMore, hasMore]);

  useEffect(() => {
    const currentRef = ref.current;
    if (currentRef) {
      currentRef.addEventListener('scroll', handleScroll);
    }
    return () => {
      if (currentRef) {
        currentRef.removeEventListener('scroll', handleScroll);
      }
    };
  }, [ref, handleScroll]);
};

apps/kg/components/general/pagination/in.content:
import Image from 'next/image';
import ArrowLeft from '../icon/arrow-left.svg';
import ArrowRight from '../icon/arrow-right.svg';

type Tpagination = {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
};

const Pagination = ({ currentPage, totalPages, onPageChange }: Tpagination) => {
  const handlePrevClick = () => {
    if (currentPage > 1) {
      onPageChange(currentPage - 1);
    }
  };

  const handleNextClick = () => {
    if (currentPage < totalPages) {
      onPageChange(currentPage + 1);
    }
  };

  const handlePageClick = (page: number) => {
    onPageChange(page);
  };

  const getPageNumbers = () => {
    const pageNumbers = [];

    // Case when totalPages is less than 4
    if (totalPages <= 4) {
      for (let i = 1; i <= totalPages; i++) {
        pageNumbers.push(i);
      }
    } else if (currentPage <= 2) {
      // First page, next page, third page, triple dots, last page
      pageNumbers.push(1, 2, 3, '...', totalPages);
    } else if (currentPage >= totalPages - 1) {
      // First page, triple dots, second-to-last page, last page
      pageNumbers.push(1, '...', totalPages - 2, totalPages - 1, totalPages);
    } else {
      // First page, triple dots, current page, next page, last page
      pageNumbers.push(1, '...', currentPage, currentPage + 1, totalPages);
    }

    return pageNumbers;
  };

  return (
    <div className="flex items-center justify-center my-4">
      <button
        // className="group p-2 rounded-md hover:bg-blue-base text-sm disabled:bg-white"
        className="group p-2 rounded-md hover:bg-sky-base text-sm disabled:bg-white"
        onClick={handlePrevClick}
        disabled={currentPage === 1}
      >
        <Image src={ArrowLeft} alt="Article Icon" width={7} height={7} />
      </button>
      <div className="mx-2">
        {getPageNumbers().map((page, index) => (
          <button
            key={index}
            // className={`mx-1 px-3 py-2 rounded-md text-sm font-semibold text-neutral-500 ${
            //   page === currentPage
            //     ? 'bg-blue-base text-white'
            //     : 'hover:bg-blue-base/90 hover:text-white'
            // }`}
            className={`mx-1 px-3 py-2 rounded-md text-sm font-semibold text-neutral-500 ${
              page === currentPage
                ? 'bg-sky-base text-white'
                : 'hover:bg-sky-base/90 hover:text-white'
            }`}
            onClick={() => {
              if (typeof page === 'number') {
                handlePageClick(page);
              }
            }}
          >
            {page}
          </button>
        ))}
      </div>

      <button
        className="group p-2 text-sm rounded-md hover:bg-blue-base disabled:bg-white"
        onClick={handleNextClick}
        disabled={currentPage === totalPages}
      >
        <Image src={ArrowRight} alt="Article Icon" width={7} height={7} />
      </button>
    </div>
  );
};

export default Pagination;

