// Error message keys
const ERROR_KEYS = {
  INSTAGRAM_FOLLOW_REQUIRED: 'INSTAGRAM_FOLLOW_REQUIRED',
  TIKTOK_FOLLOW_REQUIRED: 'TIKTOK_FOLLOW_REQUIRED',
  YOUTUBE_SUBSCRIBE_REQUIRED: 'YOUTUBE_SUBSCRIBE_REQUIRED',
  USERNAME_REQUIRED: 'USERNAME_REQUIRED',
} as const;

// Social media links
