import {
  facultyRequest,
  majorContractRequest,
  majorEnrollRequest,
  majorGetByIdRequest,
  studentSubjectDeletePlanRequest,
  studentSubjectPengajuanRequest,
  studentSubjectPlanRequest,
  studentSubjectSendDraftRequest,
} from './request';
