export const useFaculty = (): UseQueryResult<
  TFacultyResponse,
  TMetaErrorResponse
> => {
  const { data: session } = useSession();
  return useQuery({
    enabled: !!session,
    queryKey: ['get-faculty'],
    queryFn: async () => await facultyRequest(),
  });
};

export const useMajorById = (
  id: string | number
): UseQueryResult<TMajorResponse, TMetaErrorResponse> => {
  const { data: session } = useSession();
