    {
      amount: 2500,
      title: 'Pendaftar',
      icon: <IconUser />,
    },
    {
      amount: 1000,
      title: 'Mahasiswa',
      icon: <IconMultiUser />,
    },
    {
      amount: 50,
      title: 'Matakuliah',
      icon: <IconBoard />,
    },
    {
      amount: 3,
      title: 'Fakultas',
      icon: <IconBuilding />,
    },
  ];

  return (
    <div>
      <div className="flex justify-between gap-7">
        {cardItems.map((card, i) => (
          <Card
            amount={card.amount}
            title={card.title}
            logo={card.icon}
            key={i}
