        </div>

        <div className="h-full w-full">
          <h1 className="font-bold text-lg mb-3">Jadwal Acara Kampus</h1>
          <div className="relative bg-white h-full rounded-lg shadow-[0_8px_30px_rgb(0,0,0,0.12)]">
