                  const Day = new Date(event.date_start.slice(0, 10));
                  const newDay = new Intl.DateTimeFormat('id', {
                    dateStyle: 'full',
                  }).format(Day);
                  return (
                    <Fragment key={i}>
                      <JadwalMk
                        image={event.thumbnail}
                        title={event.name}
                        dateEven={newDay}
                        time={event.date_end.slice(11, 16)}
