const StudentInboxModule: React.FC = () => {
  // const [accessToken, setAccessToken] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [openedUser, setOpenedUser] = useState<Contact | null>(null);

