  //       setIsSocketConnected(isConnected);
  //       if (!isConnected) {
  //         console.log('Connection failed. Retrying in 3 seconds...');
  //         setRetryCount(prevCount => prevCount + 1);
  //       } else {
  //         setRetryCount(0);
  //       }
  //     }, 1000);
  //   } else if (socketService.isConnected()) {
