                    onClick={() => setIsModalStartNewChatOpen(true)}
                  >
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="24"
                      height="24"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      className="h-4 w-4"
                    >
                      <path d="M5 12h14"></path>
                      <path d="M12 5v14"></path>
                    </svg>
                  </button>
                </h3>
              </div>
              <StudentInboxChatList
                onSelectConversation={handleSelectConversation}
                socketService={socketService}
                selectedUserId={openedUser?.id}
              />
            </div>
          </div>
          <div
            className={`${
              openedUser || isLoadingChat ? 'block' : 'hidden'
            } lg:block lg:w-8/12 xl:w-3/4 h-full`}
          >
            {openedUser ? (
              <div className="flex h-full flex-col">
                {/* Chat Header */}
                <div className="border-b border-gray-200 px-4 py-3 flex items-center space-x-3">
                  <button
                    onClick={onBack}
                    className="text-gray-600 hover:text-gray-800"
                  >
                    <svg
                      className="h-6 w-6"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M10 19l-7-7m0 0l7-7m-7 7h18"
