apps/kg-admin/modules/pengajuan/konversi.content:
'use client';

import { Dialog, Transition } from '@headlessui/react';
import { useQueryClient } from '@tanstack/react-query';
import { FC, Fragment } from 'react';
import { BsCheckCircleFill } from 'react-icons/bs';
import { useRecoilState } from 'recoil';
import { useAccRejectConversion } from '../../../../hooks/pengajuan/konversi/hooks';
import { modalAccOpen } from '../store';
import { TAccRejectModal } from '../types';
import { toast } from 'react-toastify';

export const ModalAcc: FC<TAccRejectModal> = ({ isOpen, request_id }) => {
  const queryClient = useQueryClient();
  const [getModalAccOpen, setModalAccOpen] = useRecoilState(modalAccOpen);

  const { mutate, isLoading } = useAccRejectConversion();

  const handleAcceptConversion = () => {
    const params = {
      request_id: request_id,
      action_type: 'APPROVED',
    };
    mutate(params, {
      onSuccess: () => {
        queryClient.invalidateQueries(['get-conversion-request']);
        setModalAccOpen(false);
        toast.success('Berhasil Menyetujui Konversi');
      },
    });
  };

  const handleCloseModal = () => {
    setModalAccOpen(false);
  };

  return (
    <>
      <Transition appear show={isOpen} as={Fragment}>
        <Dialog
          as="div"
          className="relative z-[100]"
          onClose={handleCloseModal}
        >
          <Transition.Child
            as={Fragment}
            enter="ease-out duration-300"
            enterFrom="opacity-0"
            enterTo="opacity-100"
            leave="ease-in duration-200"
            leaveFrom="opacity-100"
            leaveTo="opacity-0"
          >
            <div className="fixed inset-0 bg-black bg-opacity-25" />
          </Transition.Child>

          <div className="fixed inset-0 overflow-y-auto">
            <div className="flex min-h-full items-center justify-center p-4 text-center">
              <Transition.Child
                as={Fragment}
                enter="ease-out duration-300"
                enterFrom="opacity-0 scale-95"
                enterTo="opacity-100 scale-100"
                leave="ease-in duration-200"
                leaveFrom="opacity-100 scale-100"
                leaveTo="opacity-0 scale-95"
              >
                <Dialog.Panel className="w-full sm:min-w-[500px] max-w-md transform overflow-hidden rounded-2xl bg-white p-6 text-center align-middle shadow-xl transition-all flex justify-center items-center flex-col">
                  <BsCheckCircleFill size={30} color="#3EB449" />
                  <Dialog.Title
                    as="h3"
                    className="text-lg font-bold leading-6 text-gray-900 my-3"
                  >
                    Konfirmasi
                  </Dialog.Title>

                  <p className="text-lg  mt-3">
                    Apakah anda ingin menyetujui pengajuan Konversi ini?
                  </p>
                  <div className="flex gap-3 justify-center w-full mt-3">
                    <button
                      type="button"
                      className="w-[250px] text-white px-5 py-2 bg-primary-500 rounded-lg border-2 border-transparent border-solid"
                      onClick={() => handleAcceptConversion()}
                    >
                      {isLoading ? 'Loading...' : 'Setujui'}
                    </button>
                    <button
                      type="button"
                      onClick={handleCloseModal}
                      className="w-[250px] text-primary-500 px-5 py-2 bg-white rounded-lg border-2 border-primary-500 border-solid"
                    >
                      Kembali
                    </button>
                  </div>
                </Dialog.Panel>
              </Transition.Child>
            </div>
          </div>
        </Dialog>
      </Transition>
    </>
  );
};

apps/kg/hooks/ruang-diskusi/hooks.ts.content:
import {
  UseMutationResult,
  UseQueryResult,
  useMutation,
  useQuery,
} from '@tanstack/react-query';
import {
  TCommentResponse,
  TCommentsPayload,
  TDiscussionDetailResponse,
  TDiscussionPayload,
  TDiscussionResponse,
  TDiscussionUpdatePayload,
  TReportPayload,
} from '../../types/ruang-diskusi';
import {
  CreateComment,
  CreateDiscussion,
  CreateReply,
  DeleteComment,
  DeleteDiscussion,
  DeleteReply,
  LikeComment,
  LikeDiscussion,
  LikeReply,
  ReportComment,
  ReportDiscussion,
  ReportReply,
  UpdateComment,
  UpdateDiscussion,
  UpdateReply,
  getAllCommentRequest,
  getAllRepliesRequest,
  getCommentByIdRequest,
  getDisscussionRequest,
} from './request';
import { TMetaErrorResponse, TMetaResponseSingle } from '@kampus-gratis/utils';
import { comment } from 'postcss';

export const useGetAllDiscussion = (
  limit: string,
  order: string,
  title: string,
  page: string,
  session_id?: string
): UseQueryResult<TDiscussionResponse> =>
  useQuery({
    queryKey: ['get-all-discussion', limit, order, title, page, session_id],
    queryFn: async () =>
      await getDisscussionRequest(limit, order, title, page, session_id),
  });

export const useGetCommentById = (
  id: string
): UseQueryResult<TCommentResponse> =>
  useQuery({
    queryKey: ['comment-get-by-id', id],
    queryFn: async () => await getCommentByIdRequest(id),
  });

export const useGetAllComment = (
  id: string
): UseQueryResult<TCommentResponse> =>
  useQuery({
    queryKey: ['get-all-comment', id],
    queryFn: async () => await getAllCommentRequest(id),
  });

export const useGetAllReplies = (
  id: string,
  comment_id: string
): UseQueryResult<TCommentResponse> =>
  useQuery({
    queryKey: ['get-all-replies', id, comment_id],
    queryFn: async () => await getAllRepliesRequest(id, comment_id),
  });

export const useCreateDiscussion = (): UseMutationResult<
  TDiscussionDetailResponse,
  TMetaErrorResponse,
  TDiscussionPayload,
  unknown
> => {
  return useMutation({
    mutationKey: ['create-discussion'],
    mutationFn: async (payload) => await CreateDiscussion(payload),
  });
};

export const useUpdateDiscussion = (
  id: string
): UseMutationResult<
  TDiscussionDetailResponse,
  TMetaErrorResponse,
  TDiscussionUpdatePayload
> => {
  return useMutation({
    mutationKey: ['update-discussion', id],
    mutationFn: async (payload) => await UpdateDiscussion(id, payload),
  });
};

export const useDeleteDiscussion = (): UseMutationResult<
  TDiscussionResponse,
  TMetaErrorResponse,
  string
> => {
  return useMutation({
    mutationKey: ['delete-discussion'],
    mutationFn: async (id: string) => await DeleteDiscussion(id),
  });
};

export const useLikeDiscussion = (
  id: string
): UseMutationResult<TDiscussionResponse, TMetaErrorResponse> => {
  return useMutation({
    mutationKey: ['like-discussion', id],
    mutationFn: async () => await LikeDiscussion(id),
  });
};

export const useReportDiscussion = (
  id: string
): UseMutationResult<
  TDiscussionDetailResponse,
  TMetaErrorResponse,
  TReportPayload
> => {
  return useMutation({
    mutationKey: ['report-discussion', id],
    mutationFn: async (payload) => await ReportDiscussion(id, payload),
  });
};

export const useCreateComment = (
  id: string
): UseMutationResult<
  TCommentResponse,
  TMetaErrorResponse,
  TCommentsPayload
> => {
  return useMutation({
    mutationKey: ['create-comment', id],
    mutationFn: async (payload) => await CreateComment(id, payload),
  });
};

export const useUpdateComment = (
  discussion_id: string,
  id: string
): UseMutationResult<
  TCommentResponse,
  TMetaErrorResponse,
  TCommentsPayload
> => {
  return useMutation({
    mutationKey: ['update-comment', discussion_id, id],
