        type === 'trueAnswer'
          ? 'bg-success-100 hover:bg-success-200'
          : type === 'falseAnswer'
          ? 'bg-[#FEDBD7] hover:bg-warning-100/80'
          : type === 'timeFinished'
          ? 'bg-[#FEF6D0] hover:bg-yellow-200'
          : type === 'totalQuestions' && 'bg-neutral-200 hover:bg-neutral-300'
