  detail: TAssignmentDetail
  assignment: TAssignmentDetail;
};

export type TAssignmentDetail = {
  id: string
  session_id: string
  session_no: number
  title: string
  desc: string
  duration_days: number
  documents: TAssignmentDocument[]
