export const faqData = [
  {
    question: 'Apa itu Paket C Gratis?',
    answer:
      'Paket C Gratis adalah program pendidikan setara SMA yang dapat diikuti secara online tanpa biaya. Selain pendidikan formal, peserta juga bisa memperoleh bimbingan belajar, tes minat bakat, tes kepemimpinan dan psikologis, try out, serta pelatihan berbasis kompetensi atau bootcamp.',
  },
  {
    question: 'Siapa yang bisa mengikuti Paket C Gratis?',
    answer:
      'Program ini terbuka untuk:<br/><br/>• Lulusan Paket B (setara SMP)<br/>• Putus sekolah setingkat SMA<br/>• Masyarakat yang ingin melanjutkan pendidikan formal setara SMA<br/>• Pekerja/karyawan yang ingin mendapatkan ijazah setara SMA',
  },
  {
    question: 'Apakah benar-benar gratis?',
    answer:
      'Ya, seluruh biaya pendidikan 100% ditanggung oleh kami. Peserta hanya perlu berkomitmen mengikuti kelas dan menyelesaikan program hingga lulus.',
  },
  {
    question: 'Apakah ijazah Paket C diakui pemerintah?',
    answer:
      'Ya. Ijazah yang diterbitkan setara dengan SMA/MA dan diakui oleh Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi (Kemendikbudristek).',
  },
  {
    question: 'Bagaimana sistem belajarnya?',
    answer: 'Sistem belajar bisa dilakukan secara online (melalui website).',
  },
  {
    question: 'Jurusan apa saja yang tersedia di Paket C Gratis?',
    answer:
      'Peserta bisa memilih jurusan sesuai minat:<br/><br/>• IPA (Ilmu Pengetahuan Alam)<br/>• IPS (Ilmu Pengetahuan Sosial)',
  },
  {
    question: 'Apakah ada batas usia untuk mendaftar?',
    answer:
      'Tidak ada batas usia ketat. Program ini terbuka untuk siapa pun yang ingin menamatkan pendidikan setara SMA, baik remaja maupun orang dewasa.',
  },
  {
    question: 'Bagaimana cara mendaftar Paket C Gratis?',
    answer:
      'Pendaftaran bisa dilakukan secara online melalui website resmi Paket C Gratis. Peserta cukup mengisi formulir, melengkapi dokumen persyaratan, dan menunggu verifikasi dari kami.',
  },
  {
    question: 'Apa saja dokumen yang diperlukan untuk mendaftar?',
    answer:
      'Biasanya:<br/><br/>• Fotokopi KTP/KK<br/>• Ijazah terakhir (Paket B/SMP atau sederajat)<br/>• Pas foto terbaru',
  },
  {
    question: 'Berapa lama masa belajar Paket C Gratis?',
    answer: 'Durasi belajar umumnya 3 tahun (sama seperti SMA reguler).',
  },
  {
    question: 'Apakah setelah lulus bisa melanjutkan kuliah?',
    answer:
      'Ya. Lulusan Paket C bisa melanjutkan ke perguruan tinggi negeri maupun swasta, baik di dalam negeri maupun luar negeri, karena ijazah diakui setara SMA.',
  },
  {
    question: 'Apakah ada pelatihan tambahan selain sekolah formal?',
