apps/backend/src/models/RoleplayPairs.ts.content:
import * as Sequelize from 'sequelize';
import { DataTypes, Model, Optional } from 'sequelize';

export interface RoleplayPairsAttributes {
  id: number;
  uuid?: string;
  userInvitor: string;
  userInvitee: string;
  accepted: boolean;
  roleplayId: string;
  videoLink?: string;
  invitorInput?: string;
  inviteeInput?: string;
  score?: number;
  createdAt: Date;
  updatedAt: Date;
  deletedAt?: Date;
}

export type RoleplayPairsPk = "id";
export type RoleplayPairsId = RoleplayPairs[RoleplayPairsPk];
export type RoleplayPairsOptionalAttributes = "id" | "uuid" | "videoLink" | "invitorInput" | "inviteeInput" | "score" | "deletedAt";
export type RoleplayPairsCreationAttributes = Optional<RoleplayPairsAttributes, RoleplayPairsOptionalAttributes>;

export class RoleplayPairs extends Model<RoleplayPairsAttributes, RoleplayPairsCreationAttributes> implements RoleplayPairsAttributes {
  id!: number;
  uuid?: string;
  userInvitor!: string;
  userInvitee!: string;
  accepted!: boolean;
  roleplayId!: string;
  videoLink?: string;
  invitorInput?: string;
  inviteeInput?: string;
  score?: number;
  createdAt!: Date;
  updatedAt!: Date;
  deletedAt?: Date;


  static initModel(sequelize: Sequelize.Sequelize): typeof RoleplayPairs {
    return RoleplayPairs.init({
    id: {
      autoIncrement: true,
      type: DataTypes.INTEGER,
      allowNull: false,
      primaryKey: true
    },
    uuid: {
      type: DataTypes.UUID,
      allowNull: true
    },
    userInvitor: {
      type: DataTypes.UUID,
      allowNull: false,
      field: 'user_invitor'
    },
    userInvitee: {
      type: DataTypes.UUID,
      allowNull: false,
      field: 'user_invitee'
    },
    accepted: {
      type: DataTypes.BOOLEAN,
