import { Button } from '@kampus-gratis/components/atoms';
import { useTakeSubjectPlan } from 'apps/kg/hooks/rencana-studi/hooks';
import Image from 'next/image';
import Link from 'next/link';
import React, { useState } from 'react';
import { BsBookHalf } from 'react-icons/bs';

import { BiSolidCalendar } from 'react-icons/bi';
import { MdStickyNote2 } from 'react-icons/md';
import { toast } from 'react-toastify';
import TakeSubjectModal from './takesubjectmodal';

export interface DataCard {
  id?: string;
  name: string;
  credit: number;
  level: number;
  code: string;
  semester: number;
  thumbnail: string;
  is_taken?: boolean;
  is_available?: boolean;
  start_at?: string;
  category?: string;
  type?: string;
  slug?: string;
}

export const SubjectCard: React.FC<DataCard> = ({
  id,
  semester,
  code,
  credit,
  level,
  name,
  thumbnail,
  is_taken,
  is_available,
  start_at,
  category,
  type,
  slug,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const { mutate } = useTakeSubjectPlan();

  const handleTakeSubject = () => {
    try {
      mutate(id as string, {
        onSuccess: () => {
          toast.success('Berhasil Mengajukan Matakuliah', {
            position: 'top-right',
            autoClose: 2000,
            hideProgressBar: false,
            closeOnClick: true,
            pauseOnHover: true,
            draggable: true,
            progress: undefined,
            theme: 'light',
          });
        },
        onError: (error) => {
          if (
            error.response?.data &&
            error.response?.data.message === 'Subject cannot be taken yet'
          ) {
            toast.error('Kuliah Ini Belum Tersedia', {
              position: 'top-right',
              autoClose: 2000,
              hideProgressBar: false,
              closeOnClick: true,
              pauseOnHover: true,
              draggable: true,
              progress: undefined,
              theme: 'light',
            });
          } else if (
            error.response?.data &&
            error.response?.data.message === 'You already enroll this Subject'
          ) {
            toast.error('Kamu Telah Memilih Mata Kuliah Ini', {
              position: 'top-right',
              autoClose: 2000,
              hideProgressBar: false,
              closeOnClick: true,
              pauseOnHover: true,
              draggable: true,
              progress: undefined,
              theme: 'light',
            });
          } else {
            const errorMessage = error.response?.data.message;
            toast.error(`${errorMessage}`, {
              position: 'top-right',
              autoClose: 2000,
              hideProgressBar: false,
              closeOnClick: true,
              pauseOnHover: true,
              draggable: true,
              progress: undefined,
              theme: 'light',
            });
          }
          setIsOpen(!isOpen);
        },
      });
    } catch (err) {
      return err;
    }
  };

  return (
    <div
      id={slug}
      className="bg-white border border-gray-200 rounded-xl shadow-lg flex flex-col justify-between min-w-[300px] xl:max-w-[300px]"
    >
      <div className="w-full p-4 pb-1 relative">
        {thumbnail ? (
          <Image
            src={thumbnail || ''}
            loading="lazy"
            alt=""
            width={0}
            height={0}
            sizes="100vh"
            style={{
              width: 'auto',
              minWidth: '100%',
              height: '150px',
              objectFit: 'cover',
            }}
            className="rounded-lg"
          />
        ) : (
          <div className="h-36 bg-gray-300 rounded-lg animate-pulse" />
