                    }
                    classNameCategory={
                      item.progress_status === 'ONGOING'
                        ? 'text-sky-base'
                        : item.progress_status === 'LATE'
                        ? 'text-[#D79210]'
                        : item.progress_status === 'FINISHED'
                        ? 'text-[#2D9A41]'
                        : item.progress_status === 'GRADING'
                        ? 'text-[#737373]'
                        : ''
                    }
                    imgAssigment={
                      item.progress_status === 'ONGOING'
                        ? AssigmentAssigned
