  myStudyGetRequestV2,
  quizHistoryGetRequest,
  quizSubmitRequest,
  quizTakeGetRequest,
} from './request';
import { quizTryoutInfoDummyData } from '@kampus-gratis/apps/kg/modules/try-out/constant';
import {
  TQuizHistoryResponse,
  TQuizQuitPopup,
  TQuizSubmitPayload,
  TQuizSubmitResponse,
  TQuizTakeResponse,
  TUseRemaingTimeQuiz,
} from '@kampus-gratis/apps/kg/types/quiz';
import { useRecoilState } from 'recoil';
