                  : selectedAnswers[index]?.status === 'not-answered' &&
                    index === currentQuestion
                  ? 'font-bold bg-primary-300 text-white border-transparent'
                  : 'bg-yellow-500 text-white border-transparent'
              } `}
            >
              {index + 1}
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default QuestionList;

