apps/kg/modules/analitik/main/chart/char.content:
import { LineChart } from "@kampus-gratis/components/atoms";
import { FC, ReactElement } from "react";

export const AnalyticChart: FC = (): ReactElement => {
  const labels = [
    "Semester 1",
    "Semester 2",
    "Semester 3",
    "Semester 4",
    "Semester 5",
    "Semester 6",
  ];
  const dataLine = {
    labels: labels,
    datasets: [
      {
        label: "IPK",
        data: [0.0, 3.3, 3.0, 1.0, 1.0, 1.0],
        borderColor: "#053d3812",
        tension: 0.1,
        fill: true,
        backgroundColor: (context: any) => {
          const ctx = context.chart.ctx;
          const gradient = ctx.createLinearGradient(50, 200, 300, 0);
          gradient.addColorStop(0, "#106FA4A1");
          gradient.addColorStop(1, "#106FA400");
          return gradient;
        },
        hoverBackgroundColor: "#A3CCAB4D",
        hoverBorderColor: "#A3CCAB4D",
        pointRadius: 6,
        pointHoverRadius: 20,
        pointStyle: "circle",
        pointBackgroundColor: "#737373",
        borderWidth: 2,
      },
    ],
  };

  const optionsLine = {
    scales: {
      y: {
        max: 4.5,
        min: 0,
        ticks: {
          color: "#333333",
          stepSize: 1,
          max: 4,
          callback: function (value: any) {
            if (value === 4.5) {
              return "";
            } else {
              return value + ".00";
            }
          },
        },
        border: {
          dash: [2, 4],
        },
        grid: {
          display: true,
          color: "rgba(0, 0, 0, 0.1)",
        },
        scaleLabel: {
          display: true,
          labelString: "Value",
        },
      },
      x: {
        grid: {
          display: true,
          color: "rgba(0, 0, 0, 0.1)",
        },
        ticks: {
          display: true,
          color: "#106FA4",
          padding: 16,
        },
        border: {
          dash: [4, 4],
        },
        reverse: false,
      },
    },
    element: {
      line: {
        tension: 0,
        borderWidth: 2,
        borderColor: "rgba(47, 97, 68, 1)",
        fill: true,
        backgroundColor: "rgba(47, 97, 68, 0.3)",
      },
      point: {
        radius: 0,
        hintRadius: 0,
      },
    },
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false,
      },
    },
  };

  return (
    <div className="col-span-3 lg:col-span-2 relative bg-
    neutral-100 h-[350px] md:px-4">
      <LineChart data={dataLine} option={optionsLine} />
    </div>
  );
};

apps/kg/components/bread-crumb/index.tsx.content:
import { FC, ReactElement, Fragment } from 'react';
import Link from 'next/link';
import { TBreadCrumbProps } from './types';
import { MdChevronRight } from 'react-icons/md';

export const BreadCrumb: FC<TBreadCrumbProps> = ({
  items,
  // textColor = 'text-[#106FA4]',
  textColor = 'text-sky-base',
  bgColor = 'bg-light',
}): ReactElement => {
  return (
    <div
      className={` place-content-start w-full  py-4 !font-extrabold text-xs md:text-sm ${bgColor} px-8 md:px-14 lg:px-16 `}
      aria-label="Breadcrumb"
    >
      <div className="max-w-[1440px] grid mx-auto">
        <ol className="flex w-full items-center gap-x-2">
          {items
            ? items.map((crumb, index) => {
                const isLastItem = index === items.length - 1;
                if (!isLastItem) {
                  return (
                    <Fragment key={index}>
                      <Link
                        href={crumb.link}
                        key={index}
                        className={`inline-flex  font-[600] items-center ${textColor}`}
                      >
                        {crumb.name}
                      </Link>
                      <MdChevronRight className={`text-xl ${textColor}`} />
                    </Fragment>
                  );
                } else {
                  return (
                    <Link key={index} href={crumb.link}>
                      <span className="text-neutral-500 font-[600] cursor-pointer">
                        {crumb.name}
                      </span>
                    </Link>
                  );
                }
              })
            : []}
        </ol>
      </div>
    </div>
  );
};

