            className="bg-gray-100 p-2 rounded-md"
            onClick={handleSave}
          >
            {' '}
            <Image
              src="/icons/article-unsave.svg"
              alt={'icon-favorite'}
              width={30}
              height={30}
              loading={'lazy'}
              priority={false}
              className="w-auto h-auto"
            />
          </Button>
        )}
      </div>
    </section>
  );
};

